-- The jurisdiction gotchas, brought across from the earlier permit project.
--
-- These are the things a counter will hand a packet back for that no form
-- field asks about: Weston wants uplift testing on every re-roof, Miramar
-- wants an HOA affidavit even when the property is not in an HOA, Pembroke
-- Pines wants the contractor registered in person, Riviera Beach will not let
-- a roofing licence install new straps at all -- that is a CGC, CBC or CRC and
-- needs its own subpermit. None of it is derivable. Somebody rang the counter.
--
-- 78 rows across 22 jurisdictions in six counties.
--
-- What was left behind, and why it matters: the source table held 138 rows and
-- a third of them were not jurisdiction rules at all. A crawler had walked a
-- pair of NOA documents and filed their body text as city rules, so Boca Raton
-- and Riviera Beach "required" a 48-hour cure time before loading tile, a
-- hand-rolled selvage lap, and a call to Polyglass technical services on
-- 1-800-894-4563. Every one of the 33 rejects traced back to those two cities,
-- which is what confirmed the diagnosis rather than a hunch about the wording.
--
-- Shipping those would have been worse than shipping nothing: a contractor
-- reading "minimum cure time is 48 hours" under the heading of what Boca Raton
-- requires has been told something false about the law by an app that sounded
-- certain. A further 25 rows were filed under a county literally named
-- "Pending Detection" and are left out for the same reason -- several name
-- their own jurisdiction in the text and can be recovered later by hand, which
-- is cheap; attributing a rule to the wrong counter is not.

create table if not exists public.building_department_rules (
  id uuid primary key default gen_random_uuid(),
  county text not null,
  city text,
  rule_type text not null default 'requirement',
  permit_types text[] not null default array['roofing'],
  rule_description text not null,
  rule_action text,
  document_required text,
  is_active boolean not null default true,
  priority integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists ix_dept_rules_lookup
  on public.building_department_rules (county, city) where is_active;

-- One row per jurisdiction per rule. Re-running the seed should not double it.
create unique index if not exists uq_dept_rule
  on public.building_department_rules (county, coalesce(city, ''), md5(rule_description));

alter table public.building_department_rules enable row level security;

-- Shared reference data, like the packet manifests and the approval library:
-- one company learning that Weston wants an uplift test is worth nothing if
-- the next has to learn it again. Readable by anyone signed in; writes are
-- staff-only, because a wrong rule here misinforms everybody at once.
drop policy if exists "rules readable" on public.building_department_rules;
create policy "rules readable" on public.building_department_rules
  for select to authenticated using (true);

drop policy if exists "rules writable by admins" on public.building_department_rules;
create policy "rules writable by admins" on public.building_department_rules
  for all to authenticated
  using (public.is_company_admin()) with check (public.is_company_admin());

